<template><section class="canonical-desk ledger-page data-management">
<h1 tabindex="-1">資料管理</h1><PrivateStateStatus :loading="loading" :loaded="loaded" :error="error" :message="message" :storage="storage" :auth-required="authRequired" @reload="load"/>
<template v-if="loaded"><details><summary>保存位置與資料範圍</summary><p>{{ storage==='isolated_local_qa'?'本機隔離測試資料':'正式私人網站帳本 · 目前登入身份' }} · {{ origin }}</p><p>私人帳本包含交易、估值、回顧、研究決定、資金、匯入、持倉畫面、公司收藏、新增決策紀錄、月度研究、情境模型和人工規則。來源頁瀏覽器紀錄另行備份。</p></details>
<h2>截圖與手動新增批次</h2><p v-if="!state.journal?.intakes.length">尚無新增批次。</p><article v-for="batch in [...state.journal?.intakes||[]].reverse()" :key="batch.id" class="intake-receipt"><h3>{{ batch.created_at.slice(0,16).replace('T',' ') }} UTC · {{ batch.status==='applied'?'已保存':'已撤回' }}</h3><p>{{ batch.source_manifest.map(s=>s.name).join('、') }}</p><details><summary>查看本次新增</summary><ul><li v-for="r in batch.candidate_receipts" :key="r.candidate_id"><a v-if="r.position_id" :href="'?workspace=ledger&position='+encodeURIComponent(r.position_id)">{{ (state.snapshots||[]).find(s=>s.id===r.snapshot_id)?.symbol || state.journal.positions.find(p=>p.id===r.position_id)?.instrument?.symbol||'查看部位' }}</a> · {{ choices[r.choice] }} <span>{{ r.reason }}</span></li></ul></details><button :disabled="busy||working" @click="changeBatch(batch)">{{ batch.status==='applied'?'撤回本次新增':'復原本次新增' }}</button></article>
<details><summary>CSV 匯入與匯出</summary><a href="?workspace=ledger&view=add&method=csv">新增 CSV 成交紀錄</a><CsvImport/></details>
<TradeRecords mode="management" :active="true"/>
<section><h2>來源頁的瀏覽器紀錄</h2><p>待查與來源判斷保存在此瀏覽器 IndexedDB，與上述私人帳本備份分開。</p><button @click="backupBrowser">下載此瀏覽器的研究紀錄</button><p role="status">{{ browserMessage }}</p></section>
</template></section></template>
<script setup>
import {ref} from 'vue';import {usePrivateState} from './private-state.js';import {undoIntake,restoreIntake} from './capture-intake.mjs';import TradeRecords from './TradeRecords.vue';import CsvImport from './CsvImport.vue';import PrivateStateStatus from './PrivateStateStatus.vue';import {exportBackup} from './device-store.js';
const {state,loaded,loading,busy,error,message,storage,authRequired,load,save,context}=usePrivateState(),working=ref(false),origin=location.host,browserMessage=ref(''),choices={new:'新增獨立部位',update:'追加觀測',skip:'略過',merge_source:'合併來源'};
async function changeBatch(batch){if(working.value)return;const base=context();working.value=true;try{const next=await (batch.status==='applied'?undoIntake:restoreIntake)(state.value,batch.id);await save(next,batch.status==='applied'?'本次新增已撤回，原證據與其他資料保留。':'本次新增已復原。',base);}catch(e){error.value=e.message;}finally{working.value=false;}}
async function backupBrowser(){try{const data=await exportBackup(),a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download='investment-research-browser-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);browserMessage.value='瀏覽器研究紀錄已準備下載。';}catch{browserMessage.value='無法讀取瀏覽器紀錄，請檢查儲存權限。';}}
</script>
